  &lt;Actions xmlns:xsd=&quot;http://www.w3.org/2001/XMLSchema&quot; xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;1546&lt;/ModuleId&gt;
      &lt;FieldName&gt;TransmiteFisiereEdenred&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;0&lt;/OrderIndex&gt;
      &lt;ActionType&gt;RunSql&lt;/ActionType&gt;
      &lt;Description&gt;Verifica fisierele Edenred&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;UseTransactions&quot;:true,&quot;SqlQuery&quot;:&quot;DECLARE @TotalSucursale INT;\nDECLARE @FisiereGenerate INT;\n\nSELECT\n    @TotalSucursale = COUNT(*)\nFROM app.Sucursala;\n\nSELECT\n    @FisiereGenerate =\n        COUNT(DISTINCT LTRIM(RTRIM(fe.CodSucursala)))\nFROM app.FisierEdenred AS fe\nINNER JOIN Files AS f\n    ON f.FileId = fe.FileId\nINNER JOIN app.Sucursala AS s\n    ON LTRIM(RTRIM(s.CodSucursala))\n     = LTRIM(RTRIM(fe.CodSucursala))\nWHERE fe.Anul = @Anul\n  AND fe.Luna = @Luna;\n\nSELECT\n    CASE\n        WHEN @TotalSucursale &amp;gt; 0\n         AND ISNULL(@FisiereGenerate, 0) = @TotalSucursale\n        THEN 1\n        ELSE 0\n    END AS EstePregatit,\n\n    N&#39;Transmiterea nu este permisă: există &#39;\n    + CONVERT(NVARCHAR(10), ISNULL(@FisiereGenerate, 0))\n    + N&#39; fișiere Edenred generate din &#39;\n    + CONVERT(NVARCHAR(10), ISNULL(@TotalSucursale, 0))\n    + N&#39; sucursale. Generează fișierele lipsă și &#238;ncearcă din nou.&#39;\n    AS MesajBlocare,\n\n    ISNULL(@FisiereGenerate, 0) AS FisiereGenerate,\n    ISNULL(@TotalSucursale, 0) AS TotalSucursale;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:&quot;ValidareEdenred&quot;,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false}&lt;/ActionData&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;1546&lt;/ModuleId&gt;
      &lt;FieldName&gt;TransmiteFisiereEdenred&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;1&lt;/OrderIndex&gt;
      &lt;ActionType&gt;ShowError&lt;/ActionType&gt;
      &lt;Description&gt;Blocheaza transmiterea incompleta&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;[ValidareEdenred:MesajBlocare]&amp;lt;/p&amp;gt;&quot;}&lt;/ActionData&gt;
      &lt;Condition&gt;[ValidareEdenred:EstePregatit] == 0&lt;/Condition&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;1546&lt;/ModuleId&gt;
      &lt;FieldName&gt;TransmiteFisiereEdenred&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;2&lt;/OrderIndex&gt;
      &lt;ActionType&gt;PlantAnApp.ExecuteWorkflow.bdec668c71bf4495a8000af636aaa8eb&lt;/ActionType&gt;
      &lt;ActionData&gt;{&quot;InputHelpText&quot;:null,&quot;Anul&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;Luna&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;Email&quot;:&quot;[EmailDestinatar]&quot;,&quot;OnError&quot;:[],&quot;ContinueOnError&quot;:false}&lt;/ActionData&gt;
      &lt;Condition&gt;[ValidareEdenred:EstePregatit] == 1&lt;/Condition&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;1546&lt;/ModuleId&gt;
      &lt;FieldName&gt;TransmiteFisiereEdenred&lt;/FieldName&gt;
