      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;3&lt;/OrderIndex&gt;
      &lt;ActionType&gt;ShowToastAndContinue&lt;/ActionType&gt;
      &lt;Description&gt;Confirmare transmitere Edenred&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;Heading&quot;:null,&quot;Message&quot;:&quot;Fișierele Edenred pentru luna [GetOrSession:MonthV], anul [GetOrSession:YearV] au fost transmise cu succes către [EmailDestinatar].&amp;lt;p&amp;gt;&amp;lt;br&amp;gt;&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;success&quot;},&quot;BgColor&quot;:null,&quot;Transition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;fade&quot;},&quot;AllowToastClose&quot;:true,&quot;CallBackJsCode&quot;:null,&quot;HideTime&quot;:&quot;5000&quot;,&quot;Stack&quot;:&quot;1&quot;,&quot;ToastPosition&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;bottom-center&quot;},&quot;TextAlignment&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;left&quot;},&quot;ShowLoader&quot;:false,&quot;LoaderColor&quot;:null}&lt;/ActionData&gt;
      &lt;Condition&gt;[ValidareEdenred:EstePregatit] == 1&lt;/Condition&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;1546&lt;/ModuleId&gt;
      &lt;FieldName&gt;TransmiteFisiereEdenred&lt;/FieldName&gt;
